  <script>
    // Mood-to-Method (again) and Pricing comparator combined
    const moodMap = {
      overwhelmed: {title:'Three-week Stabilizer', text:'Short cycle to clear friction and land 1–2 reliable anchors.', cta:'Begin Stabilizer'},
      stuck: {title:'Habit Foundry Lite', text:'Identify bottlenecks and design targeted micro-tests.', cta:'Start a Lite Foundry'},
      ready: {title:'Momentum Sprint', text:'A four-week push with clear metrics and weekly review.', cta:'Join a Sprint'},
      curious: {title:'Playful Labs', text:'Low-commitment experiments to test what fits.', cta:'Explore Labs'}
    };

    const moodBtns = document.querySelectorAll('.moodBtn');
    const pathTitle = document.getElementById('pathTitle');
    const pathText = document.getElementById('pathText');
    const pathCta = document.getElementById('pathCta');

    moodBtns.forEach(b=>b.addEventListener('click', ()=>{
      moodBtns.forEach(x=>x.classList.toggle('active', x===b));
      const key = b.dataset.key;
      const m = moodMap[key];
      pathTitle.style.opacity=0; pathText.style.opacity=0; pathCta.style.transform='translateY(6px)';
      setTimeout(()=>{
        pathTitle.textContent = m.title; pathText.textContent = m.text; pathCta.textContent = m.cta; pathCta.href = '{{PRIMARY_CTA_URL}}?path='+encodeURIComponent(m.title);
        pathTitle.style.opacity=1; pathText.style.opacity=1; pathCta.style.transform='translateY(0)';
      },180);
    }));

    // pricing comparator similar to services.js
    const modeButtons = document.querySelectorAll('.modeBtn');
    const priceEls = document.querySelectorAll('.price');
    let currentMode = 'monthly';

    function animateNum(span, start, end, duration){
      const t0 = performance.now();
      function frame(t){
        const p = Math.min(1,(t-t0)/duration);
        const v = Math.round(start + (end-start)*p);
        span.textContent = v;
        if(p<1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    function switchMode(newMode){
      if(newMode===currentMode) return; currentMode=newMode;
      modeButtons.forEach(b=>b.classList.toggle('active', b.dataset.mode===newMode));
      priceEls.forEach(el=>{
        const span = el.querySelector('.pnum');
        const from = parseInt(span.textContent,10)||0;
        const to = parseInt(el.dataset[newMode],10);
        animateNum(span, from, to, 380);
        // update currency display after animation
        setTimeout(()=>{ el.innerHTML = '$<span class="pnum">'+to+'</span>'; }, 400);
      });
    }

    modeButtons.forEach(b=>b.addEventListener('click', ()=>switchMode(b.dataset.mode)));
  </script>
